/// <reference types="@stdlib/types"/>

import zeros = require( '@stdlib/ndarray/zeros' );
import ndarraylikes2objects = require( './index' );


// TESTS //

// The function returns an array of ndarray objects...
{
	const x = zeros( [ 2, 2 ] );
	ndarraylikes2objects( [ x ] ); // $ExpectType ndarrayObject[]
}

// The compiler throws an error if the function is not provided an array of ndarrays...
{
	ndarraylikes2objects( '5' ); // $ExpectError
	ndarraylikes2objects( 123 ); // $ExpectError
	ndarraylikes2objects( true ); // $ExpectError
	ndarraylikes2objects( false ); // $ExpectError
	ndarraylikes2objects( null ); // $ExpectError
	ndarraylikes2objects( [ 1 ] ); // $ExpectError
	ndarraylikes2objects( {} ); // $ExpectError
	ndarraylikes2objects( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 2, 2 ] );
	ndarraylikes2objects(); // $ExpectError
	ndarraylikes2objects( x, 5 ); // $ExpectError
}
